import{_ as i,C as o,c as t,o as l,aa as d,j as _,G as a}from"./chunks/framework.Cn7WEiMX.js";const f=JSON.parse('{"title":"变量","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"TownyAdvanced","link":"/wiki/TownyAdvanced"},{"title":"reference","link":"/wiki/TownyAdvanced/reference"},{"title":"变量","link":"/wiki/TownyAdvanced/reference/placeholders-papi"}]},"headers":[],"relativePath":"wiki/TownyAdvanced/reference/placeholders-papi.md","filePath":"wiki/TownyAdvanced/reference/placeholders-papi.md"}'),r={name:"wiki/TownyAdvanced/reference/placeholders-papi.md"},w={class:"details custom-block"};function y(v,e,s,u,m,p){const n=o("NolebaseGitContributors"),c=o("NolebaseGitChangelog");return l(),t("div",null,[e[1]||(e[1]=d('<h1 id="变量" tabindex="-1">变量 <a class="header-anchor" href="#变量" aria-label="Permalink to &quot;变量&quot;">​</a></h1><p>自 Towny 0.94.0.18 开始，插件内置了对 PlaceholderAPI 的支持，无需再从 PAPI eCloud 下载变量拓展。使用这些变量仍需安装 PlaceholderAPI 插件本身。不过目前 Towny 本体尚不支持变量，只有 TownyChat 可以使用。</p><p>如果你使用的 Towny 版本低于 0.94.0.18，你仍可以下载<a href="https://api.extendedclip.com/expansions/towny/" target="_blank" rel="noreferrer">旧的 PAPI Towny 变量拓展</a>。</p><blockquote><p>你可以在 Towny 的 config.yml <code>papi_chat_formatting</code> 部分自定义变量的返回值。（比如，去掉方括号，或者改变颜色）</p></blockquote><details class="details custom-block"><summary>按时间顺序排列</summary><h2 id="v0-95-0-0-引入" tabindex="-1">v0.95.0.0 引入 <a class="header-anchor" href="#v0-95-0-0-引入" aria-label="Permalink to &quot;v0.95.0.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_town%</code> - 返回城镇名称（若有）</li><li><code>%townyadvanced_town_formatted%</code> - 返回带格式的城镇名称（若有）</li><li><code>%townyadvanced_nation%</code> - 返回国家名称（若有）</li><li><code>%townyadvanced_nation_formatted%</code> - 返回带格式的国家名称（若有）</li><li><code>%townyadvanced_town_balance%</code> - 返回城镇银行存款</li><li><code>%townyadvanced_nation_balance%</code> - 返回国家银行存款</li><li><code>%townyadvanced_town_tag%</code> - 返回城镇标签（若有）</li><li><code>%townyadvanced_town_tag_override%</code> - 返回城镇标签（若有）或完整城镇名称</li><li><code>%townyadvanced_nation_tag%</code> - 返回国家标签（若有）</li><li><code>%townyadvanced_nation_tag_override%</code> - 返回国家标签（若有）或完整国家名称</li><li><code>%townyadvanced_towny_tag%</code> - 返回城镇及国家标签</li><li><code>%townyadvanced_towny_tag_override%</code> - 若玩家拥有城镇与国家标签，则返回，若无则返回名称</li><li><code>%townyadvanced_towny_tag_formatted%</code> - 若玩家拥有城镇与国家标签，则返回，若无则返回带格式的名称</li><li><code>%townyadvanced_title%</code> - 返回国家领袖授予的前缀</li><li><code>%townyadvanced_surname%</code> - 返回国家领袖授予的后缀</li><li><code>%townyadvanced_towny_name_prefix%</code> - 返回城镇拥有者及国家领袖的前缀</li><li><code>%townyadvanced_towny_name_postfix%</code> - 返回城镇拥有者及国家领袖的后缀</li><li><code>%townyadvanced_towny_prefix%</code> - 若有前缀，则返回，若无则返回城镇拥有者及国家领袖的前缀</li><li><code>%townyadvanced_towny_postfix%</code> - 若有后缀，则返回，若无则返回城镇拥有者及国家领袖的后缀</li><li><code>%townyadvanced_towny_colour%</code> - 返回玩家身份对应名称的颜色（详见 config.yml）</li></ul><h2 id="v0-95-1-0-引入" tabindex="-1">v0.95.1.0 引入 <a class="header-anchor" href="#v0-95-1-0-引入" aria-label="Permalink to &quot;v0.95.1.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_town_residents_amount%</code> - 返回城镇居民的数量</li><li><code>%townyadvanced_town_residents_online%</code> - 返回城镇在线居民的数量</li><li><code>%townyadvanced_town_townblocks_used%</code> - 返回城镇占领的地块数量</li><li><code>%townyadvanced_town_townblocks_bought%</code> - 返回城镇购置的地块数量</li><li><code>%townyadvanced_town_townblocks_bonus%</code> - 返回城镇额外获得的地块数量</li><li><code>%townyadvanced_town_townblocks_maximum%</code> - 返回城镇可占领的地块数量</li><li><code>%townyadvanced_town_townblocks_natural_maximum%</code> - 返回城镇可占领的地块数量，忽略奖励与购置地块数量</li><li><code>%townyadvanced_town_mayor%</code> - 返回居民所在城镇的拥有者名称</li><li><code>%townyadvanced_nation_king%</code> - 返回居民所在国家的领袖名称</li><li><code>%townyadvanced_resident_friends_amount%</code> - 返回居民的好友数量</li><li><code>%townyadvanced_nation_residents_amount%</code> - 返回居民所在国家的国民数量</li><li><code>%townyadvanced_nation_residents_online%</code> - 返回居民所在国家的在线国民数量</li><li><code>%townyadvanced_nation_capital%</code> - 返回居民所在国家首都的名称</li></ul><h2 id="v0-95-2-0-引入" tabindex="-1">v0.95.2.0 引入 <a class="header-anchor" href="#v0-95-2-0-引入" aria-label="Permalink to &quot;v0.95.2.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_daily_town_upkeep%</code> - 返回城镇的维护费用</li><li><code>%townyadvanced_daily_nation_upkeep%</code> - 返回国家的维护费用</li><li><code>%townyadvanced_has_town%</code> - 返回居民是否已经加入了城镇</li><li><code>%townyadvanced_has_nation%</code> - 返回居民是否已经加入了国家</li></ul><h2 id="v0-96-0-0-引入" tabindex="-1">v0.96.0.0 引入 <a class="header-anchor" href="#v0-96-0-0-引入" aria-label="Permalink to &quot;v0.96.0.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_nation_tag_town_formatted%</code> - 返回国家标签及完整城镇名称。若国家标签未设置，则只返回城镇名称。</li></ul><h2 id="v0-96-2-0-引入" tabindex="-1">v0.96.2.0 引入 <a class="header-anchor" href="#v0-96-2-0-引入" aria-label="Permalink to &quot;v0.96.2.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_town_ranks%</code> - 返回城镇拥有者及其他获得的职称，若无则返回空</li><li><code>%townyadvanced_nation_ranks%</code> - 返回国家领袖及其他获得的职称，若无则返回空</li><li><code>%townyadvanced_player_status%</code> - 根据玩家所处地位返回游民、居民、城镇拥有者或国家领袖</li></ul><h2 id="v0-96-3-0-引入" tabindex="-1">v0.96.3.0 引入 <a class="header-anchor" href="#v0-96-3-0-引入" aria-label="Permalink to &quot;v0.96.3.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_town_prefix%</code> - 返回玩家所属城镇在配置中设置的前缀（如：废墟、定居点）</li><li><code>%townyadvanced_town_postfix%</code> - 返回玩家所属城镇在配置中设置的后缀（如：废墟、定居点）</li><li><code>%townyadvanced_nation_prefix%</code> - 返回玩家所属国家在配置中设置的前缀（如：土地、领域）</li><li><code>%townyadvanced_nation_postfix%</code> - 返回玩家所属国家在配置中设置的后缀（如：土地、领域）</li><li><code>%townyadvanced_player_jailed%</code> - 若玩家正处于监禁状态，则返回 true。否则返回 false。</li><li><code>%townyadvanced_player_plot_type%</code> - 返回玩家所处地块的类型，如：商店，若无则返回空。</li><li><code>%townyadvanced_player_plot_owner%</code> - 返回玩家是否为地块的拥有者，若是则返回 true。</li><li><code>%townyadvanced_nation_tag_town_name%</code> - 返回国家标签（若有，否则返回空）及城镇名称（若玩家已经加入城镇）</li><li><code>%townyadvanced_daily_town_tax%</code> - 返回城镇向居民收取的每日税额</li><li><code>%townyadvanced_daily_nation_tax%</code> - 返回国家向城镇收取的每日税额</li></ul><h2 id="v0-96-6-0-引入" tabindex="-1">v0.96.6.0 引入 <a class="header-anchor" href="#v0-96-6-0-引入" aria-label="Permalink to &quot;v0.96.6.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_player_location_town_or_wildname%</code> - 返回玩家所在城镇或郊区名称</li><li><code>%townyadvanced_player_location_formattedtown_or_wildname%</code> - 返回玩家所在城镇或郊区的格式化名称</li><li><code>%townyadvanced_player_location_town_prefix%</code> - 返回玩家的前缀，若无则返回空</li><li><code>%townyadvanced_player_location_town_postfix%</code> - 返回玩家的后缀，若无则返回空</li><li><code>%townyadvanced_player_location_pvp%</code> - 根据所处位置是否开放 PVP 返回开启状态，若无则返回空</li><li><code>%townyadvanced_nation_map_color_hex%</code> - 返回命令 <code>/t set mapcolor</code> 中设置（详见 dynmap-towny）的国家的十六进制颜色值</li></ul><h2 id="v0-96-7-0-引入" tabindex="-1">v0.96.7.0 引入 <a class="header-anchor" href="#v0-96-7-0-引入" aria-label="Permalink to &quot;v0.96.7.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_is_nation_peaceful%</code> - 如果玩家所属国家为和平状态，则返回 <code>status_town_title_peaceful</code> 设置的值，默认为 <code>&amp;b(和平状态)</code></li><li><code>%townyadvanced_is_town_peaceful%</code> - 如果玩家所属城镇为和平状态，则返回 <code>status_town_title_peaceful</code> 设置的值，默认为 <code>&amp;b(和平状态)</code></li><li><code>%townyadvanced_player_location_plot_name%</code> - 若有，则返回地皮的名称。</li><li>有关变量：<code>%rel_townyadvanced_color%</code><ul><li>给名称加上 config.yml 新增的 <code>papi_relational_formatting</code> 部分所指的颜色</li><li>可以用于 TAB 或其他插件的相关变量中。</li></ul></li></ul><h2 id="v0-97-1-0-引入" tabindex="-1">v0.97.1.0 引入 <a class="header-anchor" href="#v0-97-1-0-引入" aria-label="Permalink to &quot;v0.97.1.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_player_location_plot_owner_name%</code> - 返回地皮拥有者，若无人拥有则返回空</li><li><code>%townyadvanced_town_map_color_hex%</code> - 返回城镇设置的颜色</li></ul><h2 id="v0-97-2-0-引入" tabindex="-1">v0.97.2.0 引入 <a class="header-anchor" href="#v0-97-2-0-引入" aria-label="Permalink to &quot;v0.97.2.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_player_location_town_resident_count%</code> - 若玩家所处位置属于某个城镇，返回城镇中的居民数量</li><li><code>%townyadvanced_player_location_town_mayor_name%</code> - 若玩家所处位置属于某个城镇，返回城镇拥有者的名称</li><li><code>%townyadvanced_player_location_town_nation_name%</code> - 若玩家所处位置属于某个城镇且它属于某个国家，返回国家的名称</li></ul><h2 id="v0-97-3-0-引入" tabindex="-1">v0.97.3.0 引入 <a class="header-anchor" href="#v0-97-3-0-引入" aria-label="Permalink to &quot;v0.97.3.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_town_board%</code> - 返回玩家所属城镇的公告消息</li><li><code>%townyadvanced_nation_board%</code> - 返回玩家所属国家的公告消息</li><li><code>%townyadvanced_player_location_town_board%</code> - 返回玩家所处城镇的公告消息</li><li><code>%townyadvanced_player_location_nation_board%</code> - 返回玩家所处国家的公告消息</li></ul><h2 id="v0-98-0-0-引入" tabindex="-1">v0.98.0.0 引入 <a class="header-anchor" href="#v0-98-0-0-引入" aria-label="Permalink to &quot;v0.98.0.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_player_location_plotgroup_name%</code> - 若玩家所在位置有地皮组，则返回地皮组的名称</li><li><code>%townyadvanced_player_location_plot_forsale%</code> - 若地皮处于挂售状态，则返回语言文件中的“地皮挂售”对应字符串</li><li><code>%townyadvanced_is_town_public%</code> - 若城镇处于对外开放状态，则返回语言文件中的“开放状态”字符串</li><li><code>%townyadvanced_is_town_open%</code> - 若玩家所属的城镇处于对外开放状态，则返回语言文件中的“开放状态”字符串</li></ul><h2 id="v0-98-2-0-引入" tabindex="-1">v0.98.2.0 引入 <a class="header-anchor" href="#v0-98-2-0-引入" aria-label="Permalink to &quot;v0.98.2.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_time_until_new_day_hours_raw%</code> - 返回新城镇日到来的剩余小时数</li><li><code>%townyadvanced_time_until_new_day_minutes_raw%</code> - 返回新城镇日到来的剩余分钟数</li><li><code>%townyadvanced_time_until_new_day_seconds_raw%</code> - 返回新城镇日到来的剩余秒钟数</li><li><code>%townyadvanced_time_until_new_day_formatted%</code> - 返回新城镇日到来的剩余时间，带格式且跟随玩家选择语言</li><li><code>%townyadvanced_time_until_new_day_hours_formatted%</code> - 返回新城镇日到来的剩余小时数，带格式且跟随玩家选择语言</li><li><code>%townyadvanced_time_until_new_day_minutes_formatted%</code> - 返回新城镇日到来的剩余分钟数，带格式且跟随玩家选择语言</li><li><code>%townyadvanced_time_until_new_day_seconds_formatted%</code> - 返回新城镇日到来的剩余秒钟数，带格式且跟随玩家选择语言</li></ul><h2 id="v0-98-3-0-引入" tabindex="-1">v0.98.3.0 引入 <a class="header-anchor" href="#v0-98-3-0-引入" aria-label="Permalink to &quot;v0.98.3.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_town_creation_cost%</code> - 返回城镇建立的价格</li><li><code>%townyadvanced_nation_creation_cost%</code> - 返回国家建立的价格</li><li><code>%townyadvanced_number_of_towns_in_server%</code> - 返回服务器上的城镇总数</li><li><code>%townyadvanced_number_of_neutral_towns_in_server%</code> - 返回服务器上的中立城镇总数</li><li><code>%townyadvanced_number_of_towns_in_world%</code> - 返回与玩家在同一世界有占领地块的城镇数量</li><li><code>%townyadvanced_number_of_neutral_towns_in_world%</code> - 返回与玩家在同一世界有占领地块的中立城镇数量</li></ul><h2 id="v0-98-4-0-引入" tabindex="-1">v0.98.4.0 引入 <a class="header-anchor" href="#v0-98-4-0-引入" aria-label="Permalink to &quot;v0.98.4.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_daily_town_per_plot_upkeep%</code> - 返回城镇每块地块的维护费用</li><li><code>%townyadvanced_daily_town_overclaimed_per_plot_upkeep_penalty%</code> - 返回城镇每块地块的额外维护费用</li><li><code>%townyadvanced_daily_town_upkeep_reduction_from_town_level%</code> - 返回城镇受其等级 <code>upkeepModifier</code> 影响获得的维护费折扣，若玩家不属于任何城镇，则返回只有一个玩家的城镇的维护费用</li><li><code>%townyadvanced_daily_town_upkeep_reduction_from_nation_level%</code> - 返回城镇受其等级 <code>nationTownUpkeepModifier</code> 影响获得的维护费折扣，若玩家不属于任何国家，则返回只有一个玩家的国家的维护费用</li><li><code>%townyadvanced_daily_nation_per_town_upkeep%</code> - 返回国家中城镇的平均维护费用</li><li><code>%townyadvanced_daily_nation_upkeep_reduction_from_nation_level%</code> - 返回国家受其等级 <code>nationTownUpkeepModifier</code> 影响获得的维护费折扣，若玩家不属于任何国家，则返回只有一个玩家的国家的维护费用</li><li><code>%townyadvanced_town_merge_cost%</code> - 返回合并城镇所需的基础费用</li><li><code>%townyadvanced_town_merge_per_plot_percentage%</code> - 返回被合并城镇需要支付的地块费用</li><li><code>%townyadvanced_town_reclaim_cost%</code> - 返回收复城镇的费用</li><li><code>%townyadvanced_town_reclaim_max_duration_hours%</code> - 返回城镇被删除前可保持废弃状态的时间上限</li><li><code>%townyadvanced_town_reclaim_min_duration_hours%</code> - 返回城镇被删除前可保持废弃状态的时间下限</li><li><code>%townyadvanced_townblock_buy_bonus_price%</code> - 返回通过 <code>/t buy bonus</code> 命令购买城镇地块的基础价格</li><li><code>%townyadvanced_townblock_claim_price%</code> - 返回通过 <code>/t claim</code> 命令占领城镇地块的基础价格</li><li><code>%townyadvanced_townblock_unclaim_price%</code> - 返回通过 <code>/t unclaim</code> 命令解除占领城镇地块的基础价格</li><li><code>%townyadvanced_outpost_claim_price%</code> - 返回通过 <code>/t claim outpost</code> 命令设置前哨站的基础价格</li><li><code>%townyadvanced_town_unformatted%</code> - 若玩家已经加入城镇，则返回其名称</li><li><code>%townyadvanced_nation_unformatted%</code> - 若玩家已经加入国家，则返回其名称</li><li><code>%townyadvanced_player_town_is_trusted%</code> - 根据玩家是否加入城镇且受到信任返回 true 或 false</li><li><code>%townyadvanced_player_plot_is_trusted%</code> - 根据玩家是否加入地皮且受到地皮信任返回 true 或 false</li><li><code>%townyadvanced_town_balance_unformatted%</code> - 返回城镇银行的存款数字</li><li><code>%townyadvanced_nation_balance_unformatted%</code> - 返回国家银行的存款数字</li></ul><h2 id="v0-98-5-0-引入" tabindex="-1">v0.98.5.0 引入 <a class="header-anchor" href="#v0-98-5-0-引入" aria-label="Permalink to &quot;v0.98.5.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_nation_or_town_name%</code> - 返回玩家国家名称，若无则返回城镇名称，否则返回空</li></ul><h2 id="v0-99-0-0-引入" tabindex="-1">v0.99.0.0 引入 <a class="header-anchor" href="#v0-99-0-0-引入" aria-label="Permalink to &quot;v0.99.0.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_townblock_next_claim_price%</code> - 返回占领下一块地皮的价格，计算价格时考虑所所有涨价规则</li></ul><h2 id="v0-99-1-0-引入" tabindex="-1">v0.99.1.0 引入 <a class="header-anchor" href="#v0-99-1-0-引入" aria-label="Permalink to &quot;v0.99.1.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_resident_primary_rank_spaced%</code> - 返回居民的初级等级，以空格分隔</li><li><code>%townyadvanced_player_status%</code> - 根据玩家所在位置返回游民、居民、城镇拥有者或国家领袖称号</li></ul><h2 id="v0-99-2-0-引入" tabindex="-1">v0.99.2.0 引入 <a class="header-anchor" href="#v0-99-2-0-引入" aria-label="Permalink to &quot;v0.99.2.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_town_map_color_minimessage_hex%</code> - 返回 MiniMessage 格式的城镇颜色（兼容 TownyChat）</li><li><code>%townyadvanced_nation_map_color_minimessage_hex%</code> - 返回 MiniMessage 格式的国家颜色（兼容 TownyChat）</li><li><code>%townyadvanced_top_town_balance_数字%</code> - 按城镇银行存款排序，返回指定排名的城镇名称</li><li><code>%townyadvanced_top_town_residents_数字%</code> - 按居民数量排序，返回指定排名的城镇名称</li><li><code>%townyadvanced_top_town_land_数字%</code> - 按占领地块数量排序，返回指定排名的城镇名称</li></ul><h2 id="v0-100-1-0-引入" tabindex="-1">v0.100.1.0 引入 <a class="header-anchor" href="#v0-100-1-0-引入" aria-label="Permalink to &quot;v0.100.1.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_daily_resident_tax%</code> - 返回玩家每日支付的税。返回数字为任意城镇税与地皮税之和。欠税会缓存一段时间，长度受 config.yml 中的 <code>economy.bank_account_cache_timeout</code> 设置控制。</li><li><code>%townyadvanced_daily_resident_tax_unformatted%</code> - 不带格式返回玩家每日支付的税。</li></ul><h2 id="v0-101-1-0-引入" tabindex="-1">v0.101.1.0 引入 <a class="header-anchor" href="#v0-101-1-0-引入" aria-label="Permalink to &quot;v0.101.1.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_town_formatted_with_town_minimessage_colour%</code> - 使用了配置的城镇变量格式，但以 MiniMessage 格式在城镇名称前插入颜色</li><li><code>%townyadvanced_nation_formatted_with_nation_minimessage_colour%</code> - 使用了配置的国家变量格式，但以 MiniMessage 格式在国家名称前插入颜色</li><li><code>%townyadvanced_towny_tag_override_with_minimessage_colour%</code> - 使用了配置的“全部显示”变量格式，但以MiniMessage 格式在国家或城镇名称（或设置的对应标签）前插入颜色</li><li><code>%townyadvanced_resident_join_date_unformatted%</code> - 返回玩家加入服务器的时间，以毫秒为单位</li><li><code>%townyadvanced_resident_join_date_formatted%</code> - 返回玩家加入服务器的时间，按正常时间单位分割</li><li><code>%townyadvanced_player_location_town_forsale_cost%</code> - 返回购置玩家所处位置城镇的价格，若无法购得则返回“非卖”</li></ul><h2 id="v0-102-0-0-引入" tabindex="-1">v0.102.0.0 引入 <a class="header-anchor" href="#v0-102-0-0-引入" aria-label="Permalink to &quot;v0.102.0.0 引入&quot;">​</a></h2><ul><li><code>%townyadvanced_town_tag_unformatted%</code> - 从 Towny 的 config.yml 中读取的无格式城镇标签</li><li><code>%townyadvanced_town_tag_override_unformatted%</code> - Towny 的 config.yml 中读取的城镇标签（若不设置则为名称）</li><li><code>%townyadvanced_nation_tag_unformatted%</code> - 从 Towny 的 config.yml 中读取的无格式国家标签</li><li><code>%townyadvanced_nation_tag_override_unformatted%</code> - Towny 的 config.yml 中读取的国家标签（若不设置则为名称）</li><li><code>%townyadvanced_daily_town_upkeep_unformatted%</code> - 返回无格式的城镇维护费用数量</li><li><code>%townyadvanced_daily_nation_upkeep_unformatted%</code> - 返回无格式的国家维护费用数量</li></ul></details>',5)),_("details",w,[e[0]||(e[0]=d('<summary>按类型排列</summary><h2 id="城镇与国家前缀-标签相关" tabindex="-1">城镇与国家前缀/标签相关 <a class="header-anchor" href="#城镇与国家前缀-标签相关" aria-label="Permalink to &quot;城镇与国家前缀/标签相关&quot;">​</a></h2><ul><li><code>%townyadvanced_town%</code> - 返回城镇名称（若有）</li><li><code>%townyadvanced_town_formatted%</code> - 返回带格式的城镇名称（若有）</li><li><code>%townyadvanced_town_formatted_with_town_minimessage_colour%</code> - 使用了配置的城镇变量格式，但以 MiniMessage 格式在城镇名称前插入颜色</li><li><code>%townyadvanced_town_unformatted%</code> - 若玩家已经加入城镇，则返回其名称</li><li><code>%townyadvanced_town_tag%</code> - 返回城镇标签（若有）</li><li><code>%townyadvanced_town_tag_override%</code> - 返回城镇标签（若有）或完整城镇名称</li><li><code>%townyadvanced_town_unformatted%</code> - 若玩家已经加入城镇，则返回其名称</li><li><code>%townyadvanced_town_tag_override_unformatted%</code> - Towny 的 config.yml 中读取的城镇标签（若不设置则为名称）</li><li><code>%townyadvanced_nation_or_town_name%</code> - 返回玩家国家名称，若无则返回城镇名称，否则返回空</li><li><code>%townyadvanced_nation%</code> - 返回国家名称（若有）</li><li><code>%townyadvanced_nation_formatted%</code> - 返回带格式的国家名称（若有）</li><li><code>%townyadvanced_nation_formatted_with_nation_minimessage_colour%</code> - 使用了配置的国家变量格式，但以 MiniMessage 格式在国家名称前插入颜色</li><li><code>%townyadvanced_nation_unformatted%</code> - 若玩家已经加入国家，则返回其名称</li><li><code>%townyadvanced_nation_tag_override_unformatted%</code> - Towny 的 config.yml 中读取的国家标签（若不设置则为名称）</li><li><code>%townyadvanced_towny_tag%</code> - 返回城镇及国家标签</li><li><code>%townyadvanced_towny_tag_override%</code> - 若玩家拥有城镇与国家标签，则返回，若无则返回名称</li><li><code>%townyadvanced_towny_tag_override_with_minimessage_colour%</code> - 使用了配置的“全部显示”变量格式，但以MiniMessage 格式在国家或城镇名称（或设置的对应标签）前插入颜色</li><li><code>%townyadvanced_towny_tag_formatted%</code> - 若玩家拥有城镇与国家标签，则返回，若无则返回带格式的名称</li></ul><h2 id="居民相关" tabindex="-1">居民相关 <a class="header-anchor" href="#居民相关" aria-label="Permalink to &quot;居民相关&quot;">​</a></h2><ul><li><code>%townyadvanced_title%</code> - 返回国家领袖授予的前缀</li><li><code>%townyadvanced_surname%</code> - 返回国家领袖授予的后缀</li><li><code>%townyadvanced_towny_name_prefix%</code> - 返回城镇拥有者及国家领袖的前缀</li><li><code>%townyadvanced_towny_name_postfix%</code> - 返回城镇拥有者及国家领袖的后缀</li><li><code>%townyadvanced_towny_prefix%</code> - 若有前缀，则返回，若无则返回城镇拥有者及国家领袖的前缀</li><li><code>%townyadvanced_towny_postfix%</code> - 若有后缀，则返回，若无则返回城镇拥有者及国家领袖的后缀</li><li><code>%townyadvanced_town_ranks%</code> - 返回城镇拥有者及其他获得的职称，若无则返回空</li><li><code>%townyadvanced_nation_ranks%</code> - 返回国家领袖及其他获得的职称，若无则返回空</li><li><code>%townyadvanced_resident_primary_rank%</code> - 返回居民的初级等级</li><li><code>%townyadvanced_resident_primary_rank_spaced%</code> - 返回居民的初级等级，以空格分隔</li><li><code>%townyadvanced_player_status%</code> - 根据玩家所处地位返回游民、居民、城镇拥有者或国家领袖</li><li><code>%townyadvanced_towny_colour%</code> - 返回玩家身份对应名称的颜色（详见 config.yml）</li><li><code>%townyadvanced_resident_join_date_unformatted%</code> - 返回玩家加入服务器的时间，以毫秒为单位</li><li><code>%townyadvanced_resident_join_date_formatted%</code> - 返回玩家加入服务器的时间，按正常时间单位分割</li><li><code>%townyadvanced_resident_friends_amount%</code> - 返回居民的好友数量</li><li><code>%townyadvanced_has_town%</code> - 返回居民是否已经加入了城镇</li><li><code>%townyadvanced_has_nation%</code> - 返回居民是否已经加入了国家</li><li><code>%townyadvanced_player_jailed%</code> - 若玩家正处于监禁状态，则返回 true。否则返回 false。</li></ul><h2 id="城镇相关" tabindex="-1">城镇相关 <a class="header-anchor" href="#城镇相关" aria-label="Permalink to &quot;城镇相关&quot;">​</a></h2><ul><li><code>%townyadvanced_town_residents_amount%</code> - 返回城镇居民的数量</li><li><code>%townyadvanced_town_residents_online%</code> - 返回城镇在线居民的数量</li><li><code>%townyadvanced_town_townblocks_used%</code> - 返回城镇占领的地块数量</li><li><code>%townyadvanced_town_townblocks_bought%</code> - 返回城镇购置的地块数量</li><li><code>%townyadvanced_town_townblocks_bonus%</code> - 返回城镇额外获得的地块数量</li><li><code>%townyadvanced_town_townblocks_maximum%</code> - 返回城镇可占领的地块数量</li><li><code>%townyadvanced_town_townblocks_natural_maximum%</code> - 返回城镇可占领的地块数量，忽略奖励与购置地块数量</li><li><code>%townyadvanced_town_mayor%</code> - 返回居民所在城镇的拥有者名称</li><li><code>%townyadvanced_town_prefix%</code> - 返回玩家所属城镇在配置中设置的前缀（如：废墟、定居点）</li><li><code>%townyadvanced_town_postfix%</code> - 返回玩家所属城镇在配置中设置的后缀（如：废墟、定居点）</li><li><code>%townyadvanced_is_town_peaceful%</code> - 如果玩家所属城镇为和平状态，则返回 <code>status_town_title_peaceful</code> 设置的值，默认为 <code>&amp;b(和平状态)</code></li><li><code>%townyadvanced_is_town_public%</code> - 若城镇处于对外开放状态，则返回语言文件中的“开放状态”字符串</li><li><code>%townyadvanced_is_town_open%</code> - 若玩家所属的城镇处于对外开放状态，则返回语言文件中的“开放状态”字符串</li><li><code>%townyadvanced_town_map_color_hex%</code> - 返回城镇设置的颜色</li><li><code>%townyadvanced_town_map_color_minimessage_hex%</code> - 返回 MiniMessage 格式的城镇颜色（兼容 TownyChat）</li><li><code>%townyadvanced_town_board%</code> - 返回玩家所属城镇的公告消息</li><li><code>%townyadvanced_town_reclaim_max_duration_hours%</code> - 返回城镇被删除前可保持废弃状态的时间上限</li><li><code>%townyadvanced_town_reclaim_min_duration_hours%</code> - 返回城镇被删除前可保持废弃状态的时间下限</li></ul><h2 id="国家相关" tabindex="-1">国家相关 <a class="header-anchor" href="#国家相关" aria-label="Permalink to &quot;国家相关&quot;">​</a></h2><ul><li><code>%townyadvanced_nation_residents_amount%</code> - 返回居民所在国家的国民数量</li><li><code>%townyadvanced_nation_residents_online%</code> - 返回居民所在国家的在线国民数量</li><li><code>%townyadvanced_nation_king%</code> - 返回居民所在国家的领袖名称</li><li><code>%townyadvanced_nation_capital%</code> - 返回居民所在国家首都的名称</li><li><code>%townyadvanced_nation_prefix%</code> - 返回玩家所属国家在配置中设置的前缀（如：土地、领域）</li><li><code>%townyadvanced_nation_postfix%</code> - 返回玩家所属国家在配置中设置的后缀（如：土地、领域）</li><li><code>%townyadvanced_nation_map_color_hex%</code> - 返回命令 <code>/t set mapcolor</code> 中设置（详见 dynmap-towny）的国家的十六进制颜色值</li><li><code>%townyadvanced_nation_map_color_minimessage_hex%</code> - 返回 MiniMessage 格式的国家颜色（兼容 TownyChat）</li><li><code>%townyadvanced_is_nation_peaceful%</code> - 如果玩家所属国家为和平状态，则返回 <code>status_town_title_peaceful</code> 设置的值，默认为 <code>&amp;b(和平状态)</code></li><li><code>%townyadvanced_nation_board%</code> - 返回玩家所属国家的公告消息</li></ul><h2 id="新城镇日相关" tabindex="-1">新城镇日相关 <a class="header-anchor" href="#新城镇日相关" aria-label="Permalink to &quot;新城镇日相关&quot;">​</a></h2><ul><li><code>%townyadvanced_time_until_new_day_hours_raw%</code> - 返回新城镇日到来的剩余小时数</li><li><code>%townyadvanced_time_until_new_day_minutes_raw%</code> - 返回新城镇日到来的剩余分钟数</li><li><code>%townyadvanced_time_until_new_day_seconds_raw%</code> - 返回新城镇日到来的剩余秒钟数</li><li><code>%townyadvanced_time_until_new_day_formatted%</code> - 返回新城镇日到来的剩余时间，带格式且跟随玩家选择语言</li><li><code>%townyadvanced_time_until_new_day_hours_formatted%</code> - 返回新城镇日到来的剩余小时数，带格式且跟随玩家选择语言</li><li><code>%townyadvanced_time_until_new_day_minutes_formatted%</code> - 返回新城镇日到来的剩余分钟数，带格式且跟随玩家选择语言</li><li><code>%townyadvanced_time_until_new_day_seconds_formatted%</code> - 返回新城镇日到来的剩余秒钟数，带格式且跟随玩家选择语言</li></ul><h2 id="经济相关" tabindex="-1">经济相关 <a class="header-anchor" href="#经济相关" aria-label="Permalink to &quot;经济相关&quot;">​</a></h2><ul><li><code>%townyadvanced_town_balance%</code> - 返回城镇银行存款</li><li><code>%townyadvanced_nation_balance%</code> - 返回国家银行存款</li><li><code>%townyadvanced_town_balance_unformatted%</code> - 返回城镇银行的存款数字</li><li><code>%townyadvanced_nation_balance_unformatted%</code> - 返回国家银行的存款数字</li><li><code>%townyadvanced_daily_town_upkeep%</code> - 返回城镇的维护费用</li><li><code>%townyadvanced_daily_town_upkeep_unformatted%</code> - 返回无格式的城镇维护费用数量</li><li><code>%townyadvanced_daily_nation_upkeep%</code> - 返回国家的维护费用</li><li><code>%townyadvanced_daily_nation_upkeep_unformatted%</code> - 返回无格式的国家维护费用数量</li><li><code>%townyadvanced_daily_town_tax%</code> - 返回城镇向居民收取的每日税额</li><li><code>%townyadvanced_daily_nation_tax%</code> - 返回国家向城镇收取的每日税额</li><li><code>%townyadvanced_daily_town_per_plot_upkeep%</code> - 返回城镇每块地块的维护费用</li><li><code>%townyadvanced_daily_town_overclaimed_per_plot_upkeep_penalty%</code> - 返回城镇每块地块的额外维护费用</li><li><code>%townyadvanced_daily_town_upkeep_reduction_from_town_level%</code> - 返回城镇受其等级 <code>upkeepModifier</code> 影响获得的维护费折扣，若玩家不属于任何城镇，则返回只有一个玩家的城镇的维护费用</li><li><code>%townyadvanced_daily_town_upkeep_reduction_from_nation_level%</code> - 返回城镇受其等级 <code>nationTownUpkeepModifier</code> 影响获得的维护费折扣，若玩家不属于任何国家，则返回只有一个玩家的国家的维护费用</li><li><code>%townyadvanced_daily_nation_per_town_upkeep%</code> - 返回国家中城镇的平均维护费用</li><li><code>%townyadvanced_daily_nation_upkeep_reduction_from_nation_level%</code> - 返回国家受其等级 <code>nationTownUpkeepModifier</code> 影响获得的维护费折扣，若玩家不属于任何国家，则返回只有一个玩家的国家的维护费用</li><li><code>%townyadvanced_town_creation_cost%</code> - 返回城镇建立的价格</li><li><code>%townyadvanced_nation_creation_cost%</code> - 返回国家建立的价格</li><li><code>%townyadvanced_townblock_buy_bonus_price%</code> - 返回通过 <code>/t buy bonus</code> 命令购买城镇地块的基础价格</li><li><code>%townyadvanced_townblock_claim_price%</code> - 返回通过 <code>/t claim</code> 命令占领城镇地块的基础价格</li><li><code>%townyadvanced_townblock_unclaim_price%</code> - 返回通过 <code>/t unclaim</code> 命令解除占领城镇地块的基础价格</li><li><code>%townyadvanced_outpost_claim_price%</code> - 返回通过 <code>/t claim outpost</code> 命令设置前哨站的基础价格</li><li><code>%townyadvanced_townblock_next_claim_price%</code> - 返回占领下一块地皮的价格，计算价格时考虑所所有涨价规则</li><li><code>%townyadvanced_town_merge_cost%</code> - 返回合并城镇所需的基础费用</li><li><code>%townyadvanced_town_merge_per_plot_percentage%</code> - 返回被合并城镇需要支付的地块费用</li><li><code>%townyadvanced_town_reclaim_cost%</code> - 返回收复城镇的费用</li><li><code>%townyadvanced_daily_resident_tax%</code> - 返回玩家每日支付的税。返回数字为任意城镇税与地皮税之和。欠税会缓存一段时间，长度受 config.yml 中的 <code>economy.bank_account_cache_timeout</code> 设置控制。</li><li><code>%townyadvanced_daily_resident_tax_unformatted%</code> - 不带格式返回玩家每日支付的税。</li></ul><h2 id="排行榜相关" tabindex="-1">排行榜相关 <a class="header-anchor" href="#排行榜相关" aria-label="Permalink to &quot;排行榜相关&quot;">​</a></h2><ul><li><code>%townyadvanced_top_town_balance_数字%</code> - 按城镇银行存款排序，返回指定排名的城镇名称</li><li><code>%townyadvanced_top_town_residents_数字%</code> - 按居民数量排序，返回指定排名的城镇名称</li><li><code>%townyadvanced_top_town_land_数字%</code> - 按占领地块数量排序，返回指定排名的城镇名称</li></ul><h2 id="位置相关" tabindex="-1">位置相关 <a class="header-anchor" href="#位置相关" aria-label="Permalink to &quot;位置相关&quot;">​</a></h2><ul><li><code>%townyadvanced_player_plot_type%</code> - 返回玩家所处地块的类型，如：商店，若无则返回空。</li><li><code>%townyadvanced_player_plot_owner%</code> - 返回玩家是否为地块的拥有者，若是则返回 true。</li><li><code>%townyadvanced_player_location_town_or_wildname%</code> - 返回玩家所在城镇或郊区名称</li><li><code>%townyadvanced_player_location_formattedtown_or_wildname%</code> - 返回玩家所在城镇或郊区的格式化名称</li><li><code>%townyadvanced_player_location_town_prefix%</code> - 返回玩家的前缀，若无则返回空</li><li><code>%townyadvanced_player_location_town_postfix%</code> - 返回玩家的后缀，若无则返回空</li><li><code>%townyadvanced_player_location_pvp%</code> - 根据所处位置是否开放 PVP 返回开启状态，若无则返回空</li><li><code>%townyadvanced_player_location_plot_name%</code> - 若有，则返回地皮的名称。</li><li><code>%townyadvanced_player_location_plot_owner_name%</code> - 返回地皮拥有者，若无人拥有则返回空</li><li><code>%townyadvanced_player_location_town_resident_count%</code> - 若玩家所处位置属于某个城镇，返回城镇中的居民数量</li><li><code>%townyadvanced_player_location_town_mayor_name%</code> - 若玩家所处位置属于某个城镇，返回城镇拥有者的名称</li><li><code>%townyadvanced_player_location_town_nation_name%</code> - 若玩家所处位置属于某个城镇且它属于某个国家，返回国家的名称</li><li><code>%townyadvanced_player_location_town_board%</code> - 返回玩家所处城镇的公告消息</li><li><code>%townyadvanced_player_location_nation_board%</code> - 返回玩家所处国家的公告消息</li><li><code>%townyadvanced_player_location_plotgroup_name%</code> - 若玩家所在位置有地皮组，则返回地皮组的名称</li><li><code>%townyadvanced_player_location_plot_forsale%</code> - 若地皮处于挂售状态，则返回语言文件中的“地皮挂售”对应字符串</li><li><code>%townyadvanced_player_location_town_forsale_cost%</code> - 返回购置玩家所处位置城镇的价格，若无法购得则返回“非卖”</li><li><code>%townyadvanced_player_town_is_trusted%</code> - 根据玩家是否加入城镇且受到信任返回 true 或 false</li><li><code>%townyadvanced_player_plot_is_trusted%</code> - 根据玩家是否加入地皮且受到地皮信任返回 true 或 false</li><li><code>%townyadvanced_number_of_towns_in_server%</code> - 返回服务器上的城镇总数</li><li><code>%townyadvanced_number_of_neutral_towns_in_server%</code> - 返回服务器上的中立城镇总数</li><li><code>%townyadvanced_number_of_towns_in_world%</code> - 返回与玩家在同一世界有占领地块的城镇数量</li><li><code>%townyadvanced_number_of_neutral_towns_in_world%</code> - 返回与玩家在同一世界有占领地块的中立城镇数量</li></ul><h2 id="相关变量" tabindex="-1">相关变量 <a class="header-anchor" href="#相关变量" aria-label="Permalink to &quot;相关变量&quot;">​</a></h2><ul><li><code>%rel_townyadvanced_color%</code> - 给名称加上 config.yml 新增的 <code>papi_relational_formatting</code> 部分所指的颜色。可以用于 TAB 或其他插件的相关变量中。</li></ul>',19)),a(n),a(c)])])}const b=i(r,[["render",y]]);export{f as __pageData,b as default};
